      - { name: "Electrical", bonus: 5 }
      - { name: "Mechanical", bonus: 5 }
      - { name: "Medical", only: ["Paramedic"] }
      - { name: "Military", only: ["Demolitions"] }
      - "Physical"
      - { name: "Pilot", bonus: 10 }
